import { Database } from "bun:sqlite";

const db = new Database("./workspace_data.sqlite");

export default {
  port: 3000,
  async fetch(req) {
    const url = new URL(req.url);
    const match = url.pathname.match(/^\/api\/workspaces\/([^\/]+)\/reports\/([^\/]+)\/download$/);
    if (req.method === "GET" && match) {
      const [_, workspaceId, reportId] = match;
      const authHeader = req.headers.get("authorization");
      if (!authHeader) return new Response("Unauthorized", { status: 401 });

      // Queries report directly by reportId without checking workspace ownership
      const report = db.query("SELECT file_path, file_name FROM workspace_reports WHERE id = ?").get(reportId);
      if (!report) return new Response("Report not found", { status: 404 });

      return new Response(Bun.file(report.file_path), {
        headers: {
          "Content-Disposition": `attachment; filename="${report.file_name}"`,
          "Content-Type": "application/pdf"
        }
      });
    }
    return new Response("Not Found", { status: 404 });
  }
};

