import { Database } from "bun:sqlite";
import { verifyJwt } from "./auth.js";

const db = new Database("./workspace_data.sqlite");

export default {
  port: 3000,
  async fetch(req) {
    const url = new URL(req.url);
    const match = url.pathname.match(/^\/api\/workspaces\/([^\/]+)\/reports\/([^\/]+)\/download$/);
    if (req.method === "GET" && match) {
      const [_, workspaceId, reportId] = match;
      const user = await verifyJwt(req.headers.get("authorization"));
      if (!user) return new Response("Unauthorized", { status: 401 });

      // Verify caller is an active member of the requested workspace
      const membership = db.query("SELECT role FROM workspace_members WHERE workspace_id = ? AND user_id = ?").get(workspaceId, user.id);
      if (!membership) return new Response("Forbidden", { status: 403 });

      // Constrain query strictly to both reportId and verified workspaceId
      const report = db.query("SELECT file_path, file_name FROM workspace_reports WHERE id = ? AND workspace_id = ?").get(reportId, workspaceId);
      if (!report) return new Response("Report not found", { status: 404 });

      return new Response(Bun.file(report.file_path), {
        headers: {
          "Content-Disposition": `attachment; filename="${report.file_name}"`,
          "Content-Type": "application/pdf"
        }
      });
    }
    return new Response("Not Found", { status: 404 });
  }
};
